buildContextObservation.toolDefinitionsText:
[0] Run
description: 在当前工作区内受控执行命令，返回 cwd、timeout、exitCode、stdout 和 stderr。提示：严禁执行 rmdir /s、remove-item 或 rm -rf；清理工作区临时文件时优先使用 git clean 或修改 .gitignore；在 Windows 下避免使用 ';' 复合多条命令，请使用 '&&'。
schema:
{
  "additionalProperties": false,
  "properties": {
    "command": {
      "description": "要执行的命令文本",
      "type": "string"
    },
    "cwd": {
      "description": "执行命令时的工作区内相对目录，默认 .",
      "type": "string"
    },
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "timeoutMs": {
      "description": "命令超时毫秒数，默认 10000（构建/测试/检查类命令自适应为 60000），最大 120000",
      "type": "integer"
    }
  },
  "required": [
    "command",
    "description"
  ],
  "type": "object"
}

[1] Ask
description: 向用户提问并等待其回答，适合需要用户确认、选择或补充信息后才能继续的场景；返回用户的回答（options 提供可选快捷回答）。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "options": {
      "description": "可选的预设回答选项，用户可直接点选",
      "items": {
        "type": "string"
      },
      "type": "array"
    },
    "question": {
      "description": "要向用户提出的问题",
      "type": "string"
    }
  },
  "required": [
    "question",
    "description"
  ],
  "type": "object"
}

[2] Read
description: 围绕一个路径自动收集最合适的上下文：文件会拿 path info 和首段内容，目录会拿 path info 和文件列表，带 query 时会连同搜索结果一起返回。大文件可用 startLine 分页续读。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "limit": {
      "description": "目录模式和搜索模式下的条数限制，默认 40",
      "type": "integer"
    },
    "lineCount": {
      "description": "文件模式下读取多少行，默认 80，最大 400",
      "type": "integer"
    },
    "path": {
      "description": "目标路径，默认为 .",
      "type": "string"
    },
    "paths": {
      "description": "可选的多路径聚合输入；提供后会依次对每个路径执行单路径 gather 并汇总结果",
      "items": {
        "type": "string"
      },
      "type": "array"
    },
    "query": {
      "description": "可选搜索词；提供后会进入搜索模式",
      "type": "string"
    },
    "startLine": {
      "description": "从第几行开始读取（最小 1）。显式提供时对所有模式生效，多路径下逐路径生效；未提供时文件模式从第 1 行、搜索模式自动定位命中附近片段。requestedStartLine/startLineFallback 为 output-only 聚合回显，模型不得回填（回填触发 invalid_arguments）",
      "type": "integer"
    }
  },
  "required": [
    "description"
  ],
  "type": "object"
}

[3] ReadDocument
description: 把当前工作区内的办公文档（Word/PPT/Excel/ODF/RTF/EPUB/CSV/PDF）本地转换为 GitHub 风格 Markdown 文本返回，需要提供相对路径；扫描版 PDF（无内嵌文本）不支持，转换结果超出 maxOutputBytes 时截断并在 truncated 字段给出证据。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "maxOutputBytes": {
      "description": "转换结果 Markdown 输出上限（字节），默认 524288",
      "type": "integer"
    },
    "path": {
      "description": "当前工作区内的相对文档路径（.doc/.docx/.ppt/.pptx/.xls/.xlsx/.odt/.ods/.odp/.rtf/.epub/.csv/.pdf 等）",
      "type": "string"
    }
  },
  "required": [
    "path",
    "description"
  ],
  "type": "object"
}

[4] List
description: 列出当前工作区目录下的文件和子目录，可指定相对路径和返回条数。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "limit": {
      "description": "最多返回多少个条目，默认 40",
      "type": "integer"
    },
    "path": {
      "description": "当前工作区内的相对目录路径，默认为 .",
      "type": "string"
    }
  },
  "required": [
    "description"
  ],
  "type": "object"
}

[5] Search
description: 递归搜索工作区目录内的文本内容，返回命中的路径、行号和预览。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "filePattern": {
      "description": "可选的路径子串过滤，例如 .rs 或 src/agent",
      "type": "string"
    },
    "ignoreCase": {
      "description": "是否忽略大小写，默认 true",
      "type": "boolean"
    },
    "limit": {
      "description": "最多返回多少条命中，默认 20",
      "type": "integer"
    },
    "path": {
      "description": "搜索起点目录，默认为 .",
      "type": "string"
    },
    "query": {
      "description": "要搜索的关键字或文本片段",
      "type": "string"
    },
    "regex": {
      "description": "是否按增强模式匹配 query；当前 v1 使用通配符式匹配，默认 false",
      "type": "boolean"
    }
  },
  "required": [
    "query",
    "description"
  ],
  "type": "object"
}

[6] Glob
description: 按路径 pattern 递归匹配工作区内文件，适合大代码库中的文件发现。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "limit": {
      "description": "最多返回多少条路径命中，默认 50",
      "type": "integer"
    },
    "path": {
      "description": "搜索起点目录，默认为 .",
      "type": "string"
    },
    "pattern": {
      "description": "要匹配的路径模式，例如 src/*.rs 或 *tool*",
      "type": "string"
    }
  },
  "required": [
    "pattern",
    "description"
  ],
  "type": "object"
}

[7] WebFetch
description: 抓取指定 http/https URL 的正文内容预览，不承担搜索排序职责。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "timeoutMs": {
      "description": "请求超时毫秒数，默认 15000",
      "type": "integer"
    },
    "url": {
      "description": "要抓取的 http/https URL",
      "type": "string"
    }
  },
  "required": [
    "url",
    "description"
  ],
  "type": "object"
}

[8] WebSearch
description: 执行外部搜索并返回结构化结果列表，不把抓取和搜索混为一个工具。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "limit": {
      "description": "最多返回多少条搜索结果，默认 5",
      "type": "integer"
    },
    "query": {
      "description": "外部搜索关键词",
      "type": "string"
    },
    "timeoutMs": {
      "description": "请求超时毫秒数，默认 15000",
      "type": "integer"
    }
  },
  "required": [
    "query",
    "description"
  ],
  "type": "object"
}

[9] MCPResource
description: 通过 capability registry 读取指定 MCP 资源 capability 的只读内容，不混入普通工具执行。
schema:
{
  "additionalProperties": false,
  "properties": {
    "arguments": {
      "description": "传给 resource capability 的结构化参数",
      "type": "object"
    },
    "capabilityId": {
      "description": "目标 resource capability id，例如 mcp:resource:repo-index",
      "type": "string"
    },
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    }
  },
  "required": [
    "capabilityId",
    "description"
  ],
  "type": "object"
}

[10] ToolSearch
description: 搜索 capability registry 中可用的工具候选，作为 deferred / dynamic tool discovery 入口。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "limit": {
      "description": "最多返回多少条候选，默认 8",
      "type": "integer"
    },
    "query": {
      "description": "可选查询词；为空时返回默认候选列表",
      "type": "string"
    },
    "sourceId": {
      "description": "可选 source id，用于缩小 discovery 范围",
      "type": "string"
    }
  },
  "required": [
    "description"
  ],
  "type": "object"
}

[11] Write
description: 在当前工作区内新建或整文件覆写文本文件，可控制是否允许覆盖现有文件。
schema:
{
  "additionalProperties": false,
  "properties": {
    "content": {
      "description": "要写入文件的完整文本内容",
      "type": "string"
    },
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "expectedHash": {
      "description": "可选。CAS 乐观并发守卫：当前文件的预期 SHA-256 哈希值。若磁盘文件哈希不匹配，则拒绝写入并提供自愈指引。",
      "type": "string"
    },
    "overwrite": {
      "description": "是否允许覆盖已存在文件，默认 true",
      "type": "boolean"
    },
    "path": {
      "description": "当前工作区内的相对文件路径",
      "type": "string"
    }
  },
  "required": [
    "path",
    "content",
    "description"
  ],
  "type": "object"
}

[12] Edit
description: 在当前工作区内按 oldText/newText 对文本文件做受控替换；默认只允许单一匹配。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "expectedHash": {
      "description": "可选。CAS 乐观并发守卫：当前文件的预期 SHA-256 哈希值。若磁盘文件哈希不匹配，则拒绝编辑并提供自愈指引。",
      "type": "string"
    },
    "newText": {
      "description": "替换后的新文本",
      "type": "string"
    },
    "oldText": {
      "description": "需要被替换的原始文本",
      "type": "string"
    },
    "path": {
      "description": "当前工作区内的相对文件路径",
      "type": "string"
    },
    "replaceAll": {
      "description": "是否允许替换全部匹配，默认 false",
      "type": "boolean"
    }
  },
  "required": [
    "path",
    "oldText",
    "newText",
    "description"
  ],
  "type": "object"
}

[13] BatchExecute
description: 批量执行多个工具子调用，可选并发和 continueOnError，用于一次性收集多个上下文片段。
schema:
{
  "additionalProperties": false,
  "properties": {
    "calls": {
      "description": "子调用列表，每个元素包含 name 和可选 arguments",
      "items": {
        "additionalProperties": false,
        "properties": {
          "arguments": {
            "type": "object"
          },
          "name": {
            "type": "string"
          }
        },
        "required": [
          "name"
        ],
        "type": "object"
      },
      "type": "array"
    },
    "continueOnError": {
      "description": "某个子调用失败后是否继续执行其余子调用",
      "type": "boolean"
    },
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "parallel": {
      "description": "是否并发执行；当 continueOnError=false 时会自动退回串行",
      "type": "boolean"
    }
  },
  "required": [
    "calls",
    "description"
  ],
  "type": "object"
}

[14] Plan
description: 控制会话级 Plan 状态：create / replace / merge / complete_step / start_execution，不执行任意子调用。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "op": {
      "description": "plan 控制操作：create / replace / merge / complete_step / start_execution",
      "type": "string"
    },
    "payload": {
      "description": "plan 内容（create / replace 需要）",
      "properties": {
        "kind": {
          "description": "plan 分类标签",
          "type": "string"
        },
        "steps": {
          "description": "step 规范列表",
          "items": {
            "properties": {
              "name": {
                "type": "string"
              },
              "summary": {
                "type": "string"
              }
            },
            "type": "object"
          },
          "type": "array"
        },
        "summary": {
          "description": "plan 概要描述",
          "type": "string"
        }
      },
      "type": "object"
    },
    "plan_id": {
      "description": "要修改的 plan id（replace / merge / complete_step 需要）",
      "type": "string"
    },
    "revision": {
      "description": "期望的 plan revision，用于 CAS 冲突检测（replace / merge / complete_step 需要）",
      "type": "integer"
    },
    "session_id": {
      "description": "拥有该 plan 的 session id",
      "type": "string"
    },
    "step": {
      "description": "merge 操作要追加的 step 规范",
      "properties": {
        "name": {
          "type": "string"
        },
        "summary": {
          "type": "string"
        }
      },
      "type": "object"
    },
    "step_id": {
      "description": "要标记完成的 step id（complete_step 需要）",
      "type": "string"
    }
  },
  "required": [
    "op",
    "description"
  ],
  "type": "object"
}

[15] ViewImage
description: 读取工作区内图片并返回规范化 image artifact（受控引用 + magic-byte MIME/尺寸元数据）；默认不嵌入文件字节，是否将字节发送给模型由 provider modality 决定（design Decision 11）。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "includeBytes": {
      "description": "是否在 artifact 中嵌入字节；默认 false（仅返回受控引用和元数据）",
      "type": "boolean"
    },
    "maxBytes": {
      "description": "嵌入字节时的最大文件字节数，超出标记 truncated（默认 2 MiB）",
      "type": "integer"
    },
    "maxHeight": {
      "description": "最大允许的图片高度，超出标记 truncated（默认 8192）",
      "type": "integer"
    },
    "maxWidth": {
      "description": "最大允许的图片宽度，超出标记 truncated（默认 8192）",
      "type": "integer"
    },
    "path": {
      "description": "当前工作区内的相对图片路径",
      "type": "string"
    }
  },
  "required": [
    "path",
    "description"
  ],
  "type": "object"
}

[16] TodoWrite
description: 记录并全量覆写当前任务列表以规划多步工作并展示进度；单步简单任务可跳过。在开始前为每个具体步骤添加一条 todo；当仍有工作剩余时，将正在执行的任务置为 in_progress（支持并发多个）；某个步骤经物理验证完成后，立即更新置为 completed。参数直接传入全量 todos 列表。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "session_id": {
      "description": "可选 session id，默认当前 session",
      "type": "string"
    },
    "todos": {
      "description": "全量任务列表，替换之前的列表",
      "items": {
        "properties": {
          "content": {
            "description": "任务内容，简短的祈使句描述",
            "type": "string"
          },
          "status": {
            "description": "pending (未开始) | in_progress (进行中) | completed (已完成)",
            "enum": [
              "pending",
              "in_progress",
              "completed"
            ],
            "type": "string"
          }
        },
        "required": [
          "content",
          "status"
        ],
        "type": "object"
      },
      "type": "array"
    }
  },
  "required": [
    "todos",
    "description"
  ],
  "type": "object"
}

[17] TodoList
description: 获取当前 session 记录的 todo 任务列表及状态。
schema:
{
  "additionalProperties": false,
  "properties": {
    "description": {
      "description": "用中文极简描述本次工具调用的目的，用于用户界面展示。每次调用工具时必须提供此字段。例如「读取 config.json」「搜索 TokenManager」「运行单元测试」。",
      "type": "string"
    },
    "session_id": {
      "description": "可选 session id",
      "type": "string"
    }
  },
  "required": [
